  if(!d||!d.credential||!d.challengeId)return;
  if(window.__cdqDriveGateGooglePendingV2620){
    if(cdqGoogleAuthPendingV42)return;
    cdqGoogleAuthPendingV42=true;
    cdqApiRun()
      .withSuccessHandler(function(resultat){
        cdqGoogleAuthPendingV42=false;
        window.__cdqDriveGateGooglePendingV2620=false;
        cdqGooglePromptDelegatedV42=false;
